{"version":3,"file":"fraud-app.jsdbx","sources":["../../src/client/components/fraud/FraudHeader.tsx","../../src/client/fraud-app.css","../../src/client/components/fraud/FraudHeader.css","../../src/client/components/fraud/FraudImpactStrip.css","../../src/client/components/fraud/FraudImpactStrip.tsx","../../src/client/components/fraud/FraudRiskHero.css","../../src/client/components/fraud/FraudRiskHero.tsx","../../src/client/components/fraud/FraudKpiCards.css","../../src/client/components/fraud/FraudKpiCards.tsx","../../src/client/components/fraud/RefundQueue.css","../../src/client/components/fraud/RefundQueue.tsx","../../src/client/components/fraud/AiFraudAnalysis.css","../../src/client/components/fraud/AiFraudAnalysis.tsx","../../src/client/components/fraud/FraudPatterns.css","../../src/client/components/fraud/FraudPatterns.tsx","../../src/client/components/fraud/RefundTrends.css","../../src/client/components/fraud/RefundTrends.tsx","../../src/client/components/fraud/FraudHeatmap.css","../../src/client/components/fraud/FraudHeatmap.tsx","../../src/client/components/fraud/InvestigationTimeline.css","../../src/client/components/fraud/InvestigationTimeline.tsx","../../src/client/components/fraud/TopFraudsters.css","../../src/client/components/fraud/TopFraudsters.tsx","../../src/client/components/fraud/FraudSystemStatus.css","../../src/client/components/fraud/FraudSystemStatus.tsx","../../src/client/fraud-app.tsx"],"sourcesContent":["import React, { useState, useEffect } from 'react';
import './FraudHeader.css';

export default function FraudHeader() {
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const formatted = time.toLocaleTimeString('en-IN', {
    hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true
  });
  const dateStr = time.toLocaleDateString('en-IN', {
    weekday: 'short', day: 'numeric', month: 'short', year: 'numeric'
  });

  return (
    <header className="fheader fade-in">
      <div className="fheader__left">
        <h1 className="fheader__title">
          <span className="fheader__shield">🛡️</span>
          Refund &amp; Fraud Intelligence Center
        </h1>
        <p className="fheader__subtitle">AI-Powered Refund Decision Engine</p>
      </div>
      <div className="fheader__right">
        <div className="fheader__live">
          <span className="fheader__live-dot"></span>
          LIVE
        </div>
        <div className="fheader__time-block">
          <span className="fheader__clock">{formatted}</span>
          <span className="fheader__date">{dateStr}</span>
        </div>
        <div className="fheader__bell">
          🔔<span className="fheader__bell-badge">5</span>
        </div>
        <div className="fheader__refund-count">
          <span className="fheader__count-num">612</span>
          <span className="fheader__count-label">Today's Refunds</span>
        </div>
      </div>
    </header>
  );
}
",".fraud-app {
  max-width: 1600px;
  margin: 0 auto;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  background: #0a0e1a;
  min-height: 100vh;
  color: #e2e8f0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.fraud-app *,
.fraud-app *::before,
.fraud-app *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.fraud-app .fcard {
  background: #131a2e;
  border: 1px solid #1e2a45;
  border-radius: 14px;
  padding: 24px;
}

.fraud-app .fcard--glow {
  box-shadow: 0 0 20px rgba(0, 200, 150, 0.08), inset 0 1px 0 rgba(255,255,255,0.03);
}

.fraud-app .fsection-title {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: #94a3b8;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.fraud-row {
  display: grid;
  gap: 24px;
}

.fraud-row-2 {
  grid-template-columns: 1fr 1fr;
}

@keyframes fraud-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(1.3); }
}

@keyframes fraud-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.fraud-app .fade-in {
  animation: fraud-fade-in 0.4s ease-out forwards;
}
",".fheader {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 28px;
  background: linear-gradient(135deg, #0f1629 0%, #131a2e 100%);
  border: 1px solid #1e2a45;
  border-radius: 14px;
}

.fheader__title {
  font-size: 22px;
  font-weight: 700;
  color: #e2e8f0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.fheader__shield { font-size: 26px; }

.fheader__subtitle {
  font-size: 13px;
  color: #00c896;
  margin-top: 4px;
  font-weight: 500;
}

.fheader__right {
  display: flex;
  align-items: center;
  gap: 20px;
}

.fheader__live {
  display: flex;
  align-items: center;
  gap: 6px;
  background: rgba(0, 200, 150, 0.1);
  border: 1px solid rgba(0, 200, 150, 0.3);
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  color: #00c896;
  letter-spacing: 1px;
}

.fheader__live-dot {
  width: 8px;
  height: 8px;
  background: #00c896;
  border-radius: 50%;
  animation: fraud-pulse 2s infinite;
}

.fheader__time-block {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.fheader__clock {
  font-size: 14px;
  font-weight: 600;
  color: #e2e8f0;
  font-variant-numeric: tabular-nums;
}

.fheader__date {
  font-size: 11px;
  color: #94a3b8;
}

.fheader__bell {
  position: relative;
  font-size: 20px;
  cursor: pointer;
}

.fheader__bell-badge {
  position: absolute;
  top: -4px;
  right: -6px;
  background: #ef4444;
  color: white;
  font-size: 9px;
  font-weight: 700;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.fheader__refund-count {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: rgba(59, 130, 246, 0.1);
  border: 1px solid rgba(59, 130, 246, 0.3);
  padding: 8px 16px;
  border-radius: 10px;
}

.fheader__count-num {
  font-size: 18px;
  font-weight: 700;
  color: #3b82f6;
}

.fheader__count-label {
  font-size: 10px;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
