}
","import React from 'react';
import './FraudImpactStrip.css';

const metrics = [
  { icon: '🛡️', value: '₹2.4L', label: 'Fraud Prevented', color: '#00c896' },
  { icon: '💰', value: '₹8.6L', label: 'Refund Processed', color: '#3b82f6' },
  { icon: '📊', value: '612', label: 'Requests Today', color: '#8b5cf6' },
  { icon: '✅', value: '84%', label: 'Auto Approval', color: '#00c896' },
  { icon: '👁️', value: '16%', label: 'Manual Review', color: '#f59e0b' },
  { icon: '🎯', value: '97%', label: 'Decision Accuracy', color: '#00c896' },
];

export default function FraudImpactStrip() {
  return (
    <div className="fimpact fade-in">
      {metrics.map((m) => (
        <div key={m.label} className="fimpact__item">
          <span className="fimpact__icon">{m.icon}</span>
          <span className="fimpact__value" style={{ color: m.color }}>{m.value}</span>
          <span className="fimpact__label">{m.label}</span>
        </div>
      ))}
    </div>
  );
}
