}

.frisk-hero__factor {
  display: grid;
  grid-template-columns: 24px 140px 1fr 40px;
  align-items: center;
  gap: 10px;
}

.frisk-hero__factor-icon { font-size: 16px; }

.frisk-hero__factor-name {
  font-size: 13px;
  color: #e2e8f0;
}

.frisk-hero__factor-bar {
  height: 6px;
