","import React from 'react';
import './FraudRiskHero.css';

const factors = [
  { name: 'Customer History', value: 92, icon: '👤' },
  { name: 'Order Value', value: 78, icon: '💰' },
  { name: 'Refund Frequency', value: 85, icon: '🔄' },
  { name: 'Device Fingerprint', value: 96, icon: '📱' },
  { name: 'Delivery Pattern', value: 88, icon: '🚚' },
  { name: 'Order Timing', value: 91, icon: '⏰' },
];

export default function FraudRiskHero() {
  const circumference = 2 * Math.PI * 80;
  const offset = circumference - (0.18 * circumference);

  return (
    <div className="fcard fcard--glow frisk-hero fade-in">
      <div className="frisk-hero__gauge-section">
        <div className="frisk-hero__gauge">
          <svg viewBox="0 0 180 180" className="frisk-hero__svg">
            <circle cx="90" cy="90" r="80" fill="none" stroke="#1e2a45" strokeWidth="10" />
            <circle
              cx="90" cy="90" r="80" fill="none"
              stroke="#00c896" strokeWidth="10"
              strokeLinecap="round"
              strokeDasharray={`${circumference}`}
              strokeDashoffset={`${offset}`}
              transform="rotate(-90 90 90)"
            />
          </svg>
          <div className="frisk-hero__score-block">
            <div className="frisk-hero__label-top">Fraud Risk Index</div>
            <div className="frisk-hero__score">18</div>
            <div className="frisk-hero__level frisk-hero__level--low">LOW RISK</div>
          </div>
        </div>
        <p className="frisk-hero__desc">Composite Fraud Intelligence Score</p>
      </div>
      <div className="frisk-hero__factors">
        <div className="fsection-title">Contributing Factors</div>
        {factors.map((f) => (
          <div key={f.name} className="frisk-hero__factor">
            <span className="frisk-hero__factor-icon">{f.icon}</span>
            <span className="frisk-hero__factor-name">{f.name}</span>
            <div className="frisk-hero__factor-bar">
              <div className="frisk-hero__factor-fill" style={{ width: `${f.value}%` }} />
            </div>
            <span className="frisk-hero__factor-val">{f.value}%</span>
          </div>
        ))}
      </div>
    </div>
  );
}
