","import React from 'react';
import './FraudKpiCards.css';

const kpis = [
  { label: 'Auto Approved', value: '487', trend: '+12%', icon: '✅', bars: [40,55,45,60,50,70,65] },
  { label: 'Pending Review', value: '98', trend: '-8%', icon: '⏳', bars: [60,50,45,40,35,38,30] },
  { label: 'Fraud Detected', value: '27', trend: '+3%', icon: '🚨', bars: [20,25,18,22,30,28,27] },
  { label: 'Money Saved', value: '₹2.4L', trend: '+18%', icon: '💰', bars: [30,40,35,50,55,60,72] },
  { label: 'Avg Resolution', value: '4.2min', trend: '-15%', icon: '⚡', bars: [70,60,55,50,45,42,40] },
  { label: 'Satisfaction', value: '94%', trend: '+2%', icon: '😊', bars: [80,82,85,88,90,92,94] },
];

export default function FraudKpiCards() {
  return (
    <div className="fkpi fade-in">
      {kpis.map((k) => (
        <div key={k.label} className="fkpi__card fcard">
          <div className="fkpi__header">
            <span className="fkpi__icon">{k.icon}</span>
            <span className={`fkpi__trend ${k.trend.startsWith('+') ? 'fkpi__trend--up' : 'fkpi__trend--down'}`}>
              {k.trend}
            </span>
          </div>
          <div className="fkpi__value">{k.value}</div>
          <div className="fkpi__label">{k.label}</div>
          <div className="fkpi__spark">
            {k.bars.map((b, i) => (
              <div key={i} className="fkpi__bar" style={{ height: `${b}%` }} />
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}
