","import React from 'react';
import './RefundQueue.css';

const queue = [
  { id: 'RF-4821', customer: 'Priya Sharma', store: 'Banjara Hills', amount: '₹349', reason: 'Missing item - Biryani Bowl', time: '2m ago', status: 'approved', ai: 'Auto-Approved' },
  { id: 'RF-4820', customer: 'Rahul Verma', store: 'Madhapur', amount: '₹589', reason: 'Wrong order delivered', time: '5m ago', status: 'approved', ai: 'Auto-Approved' },
  { id: 'RF-4819', customer: 'Anita K.', store: 'Jubilee Hills', amount: '₹199', reason: 'Quality issue - Stale food', time: '8m ago', status: 'pending', ai: 'Under Review' },
  { id: 'RF-4818', customer: 'Vikram P.', store: 'Kukatpally', amount: '₹1,249', reason: 'Not delivered - GPS mismatch', time: '12m ago', status: 'flagged', ai: 'Escalated' },
  { id: 'RF-4817', customer: 'Deepa M.', store: 'Gachibowli', amount: '₹429', reason: 'Damaged packaging', time: '15m ago', status: 'approved', ai: 'Auto-Approved' },
  { id: 'RF-4816', customer: 'Suresh R.', store: 'Ameerpet', amount: '₹2,100', reason: 'Multiple items missing', time: '18m ago', status: 'flagged', ai: 'Blocked' },
  { id: 'RF-4815', customer: 'Kavita D.', store: 'Hitech City', amount: '₹150', reason: 'Late delivery >45min', time: '22m ago', status: 'pending', ai: 'Under Review' },
];

export default function RefundQueue() {
  return (
    <div className="fcard refund-q fade-in">
      <div className="fsection-title">Live Refund Queue</div>
      <div className="refund-q__list">
        {queue.map((item) => (
          <div key={item.id} className={`refund-q__item refund-q__item--${item.status}`}>
            <span className={`refund-q__dot refund-q__dot--${item.status}`} />
            <div className="refund-q__main">
              <div className="refund-q__top">
                <span className="refund-q__id">{item.id}</span>
                <span className="refund-q__customer">{item.customer}</span>
                <span className="refund-q__store">{item.store}</span>
              </div>
              <div className="refund-q__reason">{item.reason}</div>
            </div>
            <span className="refund-q__amount">{item.amount}</span>
            <span className="refund-q__time">{item.time}</span>
            <span className={`refund-q__badge refund-q__badge--${item.status}`}>{item.ai}</span>
          </div>
        ))}
      </div>
    </div>
  );
}
