  { day: 'Thu', value: 110, approved: 94, flagged: 8, annotation: 'Weekend Sale' },
  { day: 'Fri', value: 125, approved: 105, flagged: 10, annotation: 'Festival Rush' },
  { day: 'Sat', value: 98, approved: 84, flagged: 7 },
  { day: 'Sun', value: 88, approved: 75, flagged: 5 },
];

const maxVal = Math.max(...days.map(d => d.value));

export default function RefundTrends() {
  return (
    <div className="fcard ftrends fade-in">
      <div className="fsection-title">7-Day Refund Trends</div>
      <div className="ftrends__legend">
