        <span className="ftrends__legend-item"><span className="ftrends__dot ftrends__dot--flagged"></span>Flagged</span>
      </div>
      <div className="ftrends__chart">
        {days.map((d) => (
          <div key={d.day} className="ftrends__col">
            {d.annotation && <span className="ftrends__annotation">{d.annotation}</span>}
            <div className="ftrends__bars">
              <div className="ftrends__bar ftrends__bar--total" style={{ height: `${(d.value / maxVal) * 100}%` }}>
                <span className="ftrends__val">{d.value}</span>
              </div>
            </div>
            <span className="ftrends__day">{d.day}</span>
          </div>
        ))}
      </div>
    </div>
  );
}
