              <td>{f.refunds}</td>
              <td>{f.amount}</td>
              <td><span className="ffraudsters__score">{f.risk}/100</span></td>
              <td>
                <span className={`ffraudsters__level ffraudsters__level--${f.level}`}>{f.level}</span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
",".fsystem {
  background: #131a2e;
  border: 1px solid #1e2a45;
