  padding: 16px 24px;
}

.fsystem__inner {
  display: flex;
  align-items: center;
  gap: 24px;
}

.fsystem__label {
  font-size: 11px;
  font-weight: 700;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 1px;
  white-space: nowrap;
}

.fsystem__items {
  display: flex;
  gap: 20px;
  flex: 1;
}

.fsystem__item {
  display: flex;
  align-items: center;
  gap: 6px;
}

.fsystem__dot {
  width: 8px;
  height: 8px;
  background: #00c896;
  border-radius: 50%;
  animation: fraud-pulse 3s infinite;
}

.fsystem__name {
  font-size: 12px;
  color: #e2e8f0;
}

.fsystem__uptime {
  font-size: 10px;
  color: #00c896;
  font-weight: 600;
}

.fsystem__all {
  font-size: 11px;
  color: #00c896;
  font-weight: 600;
  white-space: nowrap;
}
